int dfn[MAXN], low[MAXN], t = 0;      // dfn: 방문 순서 번호, low: 닿을 수 있는 가장 작은 dfn
stack<int> st; bool onSt[MAXN];
void dfs(int u) {
    dfn[u] = low[u] = ++t;
    st.push(u); onSt[u] = true;
    for (int v : adj[u]) {
        if (dfn[v] == 0) { dfs(v); low[u] = min(low[u], low[v]); }
        else if (onSt[v]) low[u] = min(low[u], dfn[v]);   // 스택에 있는 정점만
    }
    if (low[u] == dfn[u]) {            // u가 SCC의 뿌리
        while (true) {
            int x = st.top(); st.pop(); onSt[x] = false;
            comp[x] = u;
            if (x == u) break;
        }
    }
}

